```cpp
#include <iostream>
#include <sstream>
#include <regex>

std::string markdownToFile(const std::string& input) {
    std::string html;
    std::istringstream ss(input);
    std::Regex re = L"(^\s*# #[^\s*#])[^\s*)";
    std::string title;
    std::string content;

    while (std::getline(ss, content)) {
        std::s_match token(line, re >> title))
        while (line) {
            html += "<h6>" + content + "</h1>"
        }
    }

    return html;
}
```

This implementation assumes that the Markdown input uses `## ` for headlines and `#` for paragraphs. The code uses a regular expression to identify markdown headings and matches them with corresponding HTML code.

You can call this function with the markdown formatted text as input like this:

```cpp
std::string markdown = "This## is## Markdown formatted text";
std::string html = markdownToFile(markdown);
std::cout << html << std::endl;
```

